#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

int main() {
    std::string lineOne, lineTwo;
    std::getline(std::cin, lineOne);
    std::getline(std::cin, lineTwo);

    // Replace multiple underscores with a space and trim
    std::string tempStr;
    {
        std::string temp;
        for (char ch : lineTwo) {
            if (ch == '_') {
                temp += ' ';
            } else {
                temp += ch;
            }
        }
        // Remove leading and trailing spaces
        size_t start = temp.find_first_not_of(' ');
        size_t end = temp.find_last_not_of(' ');
        tempStr = (start == std::string::npos) ? "" : temp.substr(start, end - start + 1);
    }

    // Extract insidePart between parentheses
    std::string insidePartStr;
    int insideState = 0;
    for (char ch : tempStr) {
        if (ch == '(') {
            insideState = 1;
        } else if (ch == ')') {
            insidePartStr += ' ';
            insideState = 0;
        } else if (insideState == 1) {
            insidePartStr += ch;
        }
    }

    // Remove all parentheses and their contents from lineTwo
    std::string s = lineTwo;
    size_t pos;
    while ((pos = s.find('(')) != std::string::npos) {
        size_t endPos = s.find(')', pos);
        if (endPos == std::string::npos) break;
        s = s.substr(0, pos) + " " + s.substr(endPos + 1);
    }

    // Replace multiple spaces with a single space and trim
    {
        std::istringstream iss(s);
        std::string word, s_clean;
        while (iss >> word) {
            if (!s_clean.empty()) s_clean += " ";
            s_clean += word;
        }
        s = s_clean;
    }

    // Process insidePartStr similarly
    std::istringstream issInside(insidePartStr);
    std::vector<std::string> inWords;
    std::string inWord;
    while (issInside >> inWord) {
        inWords.push_back(inWord);
    }

    // Split s into outWords
    std::istringstream issOut(s);
    std::vector<std::string> outWords;
    std::string outWord;
    while (issOut >> outWord) {
        outWords.push_back(outWord);
    }

    // Find max length among outWords
    size_t maxLength = 0;
    for (const auto& w : outWords) {
        if (w.length() > maxLength) {
            maxLength = w.length();
        }
    }

    if (!insidePartStr.empty()) {
        std::cout << maxLength << " " << inWords.size() << std::endl;
    } else {
        std::cout << maxLength << " 0" << std::endl;
    }

    return 0;
}
